widget.solution:
def universe_as_of(members, date):
    """members: (firm, start, end) records, ISO date strings;
    end is the first day it is no longer a member, or None.
    Returns the sorted firms that are members on date."""
    return sorted(f for f, start, end in members
                  if start <= date and (end is None or date < end))
